#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	void *addr;
	int ret;
	int i;
	int count;
	int off;
	int val;
	int filled;
	int done;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		printf("Failed to open %s\n", argv[1]);
		return -1;
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (addr == MAP_FAILED) {
		printf("Failed to mmap %s\n", argv[1]);
		return -1;
	}

	count = 100;
	off = 0;
	done = 0;
	while (count) {
		if (count >= 4 &&!(off % 4)) {
			val = ioread32(addr + off);
			filled = 4;
		} else if (count >= 2 &&!(off % 2)) {
			val = ioread16(addr + off);
			filled = 2;
		} else {
			val = ioread8(addr + off);
			filled = 1;
		}

		count -= filled;
		done += filled;
		off += filled;
	}

	munmap(addr, PAGE_SIZE);
	close(fd);

	return 0;
}
