#define MAX_CLKS 100

struct samsung_clk_provider {
	struct device *dev;
	void __iomem *reg_base;
	struct clk_hw_onecell_data clk_data;
	spinlock_t lock;
};

struct samsung_clk_provider * __init samsung_clk_init(struct device *dev,
			void __iomem *base, unsigned long nr_clks)
{
	struct samsung_clk_provider *ctx;
	int i;

	ctx = kzalloc(struct_size(ctx, clk_data.hws, nr_clks), GFP_KERNEL);
	if (!ctx)
		panic("could not allocate clock provider context.\n");

	ctx->clk_data.num = nr_clks;
	for (i = 0; i < nr_clks; ++i)
		ctx->clk_data.hws[i] = ERR_PTR(-ENOENT);

	ctx->dev = dev;
	ctx->reg_base = base;
	spin_lock_init(&ctx->lock);

	return ctx;
}

int main(int argc, char **argv)
{
	struct samsung_clk_provider *ctx;
	int i;

	ctx = samsung_clk_init(NULL, NULL, MAX_CLKS);
	if (!ctx)
		return -1;

	for (i = 0; i < MAX_CLKS; ++i) {
		if (ctx->clk_data.hws[i] == ERR_PTR(-ENOENT))
			return -1;
	}

	return 0;
}
