            cwe_list[i] = malloc(strlen(line) + 1);
            strcpy(cwe_list[i], line);
            i++;
        }
    }

    printf("[");
    for (i = 0; i < 5; i++) {
        if (i!= 0) {
            printf(", ");
        }
        printf("\"%s\"", cwe_list[i]);
        free(cwe_list[i]);
    }
    printf("]\n");

    if (line) {
        free(line);
    }
    close(fd);
    exit(EXIT_SUCCESS);
}
